    @Override
    public BigDecimal frete(Carrinho carrinho) {
        return Dinheiro.centavos(BASE.add(POR_KG.multiply(carrinho.pesoKg())));
    }

    @Override
    public int prazoDias() {
        return 7;
    }
}
